mapper.select:
SELECT , AS appr_yn FROM tdm30_role_allc LEFT OUTER JOIN tdm20_role ON tdm20_role_id = tdm30_role_id WHERE tdm30_company_id = #{companyId}
AND #{baseDate}::date BETWEEN tdm30_start_date AND COALESCE(tdm30_end_date, TO_DATE('29991231','yyyyMMdd'))
AND CONCAT(tdm20_role_nm, f_emp_kor_nm(tdm30_person_id)) ILIKE #{searchText} ORDER BY tdm20_role_nm COLLATE "ko_KR.utf8" , tdm30_start_date , f_emp_kor_nm(tdm30_person_id) COLLATE "ko_KR.utf8"

SELECT , false AS appr_yn FROM tdm30_role_allc LEFT OUTER JOIN tdm20_role ON tdm20_role_id = tdm30_role_id WHERE tdm30_company_id = #{companyId}
AND tdm30_role_allc_id NOT IN #{roleAllcId}
ORDER BY tdm20_role_nm COLLATE "ko_KR.utf8" , tdm30_start_date , f_emp_kor_nm(tdm30_person_id) COLLATE "ko_KR.utf8"

SELECT tdm30_company_id
  FROM tdm30_role_allc
 WHERE tdm30_role_allc_id = #{roleAllcId}

mapper.update:
UPDATE tdm30_role_allc
   SET tdm30_role_id      = #{roleId}
     , tdm30_person_id    = #{personId}
     , tdm30_add_title_yn = #{addTitleYn}
     , tdm30_start_date   = #{startDate}
     , tdm30_end_date     = #{endDate}
     , tdm30_upd_nm       = #{updName}
     , tdm30_upd_date     = f_sysdate()
 WHERE tdm30_role_allc_id = #{roleAllcId}
   AND tdm30_company_id   = #{companyId}

mapper.delete:
